;; Generated by the release tooling; do not edit.
(ns rainbow.coverage.total-test
  "Every proof module (a namespace under src that defines extend-environment) must be reached by some test
  namespace through its requires. A module added without a test fails this, so coverage cannot silently drop."
  (:require [clojure.edn]
            [clojure.java.io :as io]
            [clojure.string :as string]
            [clojure.test :refer [deftest is]]))

(defn- clj-files [dir]
  (filter #(string/ends-with? (.getName ^java.io.File %) ".clj") (file-seq (io/file dir))))

(defn- ns-and-requires [f]
  (let [t (slurp f)
        n (second (re-find #"\(ns\s+([\w.\-]+)" t))
        i (string/index-of t "(:require")
        head (if i (subs t i (min (count t) (+ i 6000))) "")]
    [n (set (map second (re-seq #"\[(rainbow\.[\w.\-]+)" head))) t]))

(deftest every-proof-module-is-reached-by-a-test
  (let [src (map ns-and-requires (clj-files "src"))
        tests (map ns-and-requires (clj-files "test"))
        requires (into {} (map (fn [[n r _]] [n r]) (concat src tests)))
        proof (set (keep (fn [[n _ t]] (when (string/includes? t "(defn extend-environment") n)) src))
        reached (loop [seen #{} todo (vec (mapcat second tests))]
                  (if-let [x (peek todo)]
                    (if (seen x) (recur seen (pop todo))
                        (recur (conj seen x) (into (pop todo) (requires x))))
                    seen))
        pending (set (map str (clojure.edn/read-string (slurp "test/rainbow/coverage/pending.edn"))))
        missing (sort (remove (into reached pending) proof))]
    (is (empty? missing) (str (count missing) " proof modules reached by no test and not listed as pending: "
                              (vec (take 10 missing))))))
